pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // Batch 137 (Research note pending / Plan 116): cloudrift-ai/emmy @ 1c058c9d —
        // the matmul-optimization ladder: smem fill-chunk alignment, software-swizzle
        // shift derivation, ring-riding companion slabs, the ptxas wash pair, the
        // transport-gated bank pad, split-K legality/width/contention, the warp-spec
        // register-fit gate, and the ldmatrix x2→x4 pairing. Two read-lanes + coordinator;
        // every quote re-verified at the pin (the B31 discipline).
        // ════════════════════════════════════════════════════════════════════
        // ── smem-fill-align-chunk-not-element — the fill-chunk alignment floor (N) ──
        KernelRule {
            rule_id: "smem-fill-align-chunk-not-element".to_string(),
            gpu_concept: "A shared-memory slab's BASE alignment derives from its FILL CHUNK, not its element width: a staging fill that writes wide vector chunks (cp.async or a vectorized smem Write) faults on any shared address that is chunk-unaligned, and aligning the slab declaration to the ELEMENT leaves an f16 slab 2 B-aligned with its 16 B writes free to land at 8 mod 16. The source's fault narrative, verbatim (kernel/_stage.py:308-314): \"Aligning to the ELEMENT would leave an f16 slab 2 B-aligned and its 16 B writes free to land at 8 mod 16, which is a real fault and not a theoretical one: it is what a packed weight's odd-sized companion slabs first shifted a neighbouring slab into (compute-sanitizer, Invalid __shared__ write of size 16 bytes ... Access to 0x2c58 is misaligned).\" The derivation is one fail-closed line (_stage.py:318): return max(_swizzle_align(swizzle), _cp_async_width(cols, elem_bytes) * elem_bytes) — the swizzle mode's ask widened by the fill chunk's byte width. The chunk picker is bounded (_stage.py:96-106): \"the widest contiguous run whose byte size is a legal cp.async width (4 / 8 / 16) and that divides the inner (contiguous) slab extent\" — widest of (16, 8, 4) B that divides, else 1. The TMA arm extends the same floor to the destination: \"TMA destination smem must be aligned (cp.async.bulk.tensor faults otherwise); 128 B satisfies the NONE-swizzle box copy\" (_stage.py:284-286) with the swizzled table _SWIZZLE_SLAB_ALIGN = {NONE: 128, B32: 256, B64: 512, B128: 1024} — a box copy faults on an unaligned DESTINATION even when the swizzle is NONE. Load-side twin in the same repo: a widened LOAD proves its own static alignment — \"n=2 fp16 is NOT a freebie despite __half2's 4-byte type alignment — an odd-element offset still misses the alignment and faults with CUDA_ERROR_MISALIGNED_ADDRESS\" (050_vectorize_loads.py:176-179). Honest NotBenchable for the fault outcomes (the compute-sanitizer repro is CUDA); the derivation itself is unit-testable anywhere. Distinct from stride-align-vectorization-key (L — GLOBAL-memory stride alignment as the vectorization WIDTH key, a perf axis; this is the smem base-alignment CORRECTNESS floor from the fill chunk), from pad-uniform-pod-to-min-binding-size (host-side uniform-buffer binding-size padding), from vectorized-smem-write-no-bank-padding (A — bank CONFLICTS are a perf axis and line-sized stores need no pad; this is ALIGNMENT, a fault class, orthogonal to conflict economics), and from block-quant-weight-pad-never-extends-activations (B129 — weight-stride format padding; never activation/slab base alignment). Category N (dtype + alignment specialization). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — passes/lowering/kernel/_stage.py:96-106, :284-289, :305-318; 050_vectorize_loads.py:174-185. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: the slab's alignment comes from its ELEMENT type; the fill is\n// 16 B wide. A neighbouring odd-sized slab shifts this slab's base to\n// 8 mod 16 and the vector store faults at runtime.\n#[derive(Clone, Copy)]\nstruct StagePlan {\n    elem_bytes: usize,\n    base_align: usize, // = elem_bytes: the ELEMENT, not the chunk\n    fill_bytes: usize,\n    smem_base: usize,\n}\n\nfn stage_f16_slab(smem_base: usize) -> StagePlan {\n    StagePlan {\n        elem_bytes: 2,\n        base_align: 2, // f16 = 2 B — \"aligned\" by the element width\n        fill_bytes: 16,\n        smem_base, // 8 mod 16 after a neighbour shifted it: FAULT\n    }\n}\n\nfn write_chunk(plan: &StagePlan) -> Result<usize, String> {\n    if plan.smem_base % plan.fill_bytes != 0 {\n        return Err(\"Invalid __shared__ write of size 16: misaligned\".to_string());\n    }\n    Ok(plan.fill_bytes)\n}\n".to_string(),
            opt_pattern: "// optimized: base alignment = max(swizzle ask, fill chunk bytes) —\n// derived once, fail-closed; the TMA arm pins 128 B even unswizzled.\nconst TMA_SLAB_ALIGN: usize = 128;\n\n#[derive(Clone, Copy)]\nenum Swizzle {\n    None,\n    B32,\n    B64,\n    B128,\n}\n\nfn swizzle_align(sw: Swizzle) -> usize {\n    match sw {\n        Swizzle::None => 0,\n        Swizzle::B32 => 256,\n        Swizzle::B64 => 512,\n        Swizzle::B128 => 1024,\n    }\n}\n\nfn cp_async_width(cols: usize, elem_bytes: usize) -> usize {\n    // widest of 16/8/4 B that divides the inner span, else 1\n    for nbytes in [16usize, 8, 4] {\n        let v = nbytes / elem_bytes;\n        if elem_bytes > 0 && v >= 1 && cols % v == 0 {\n            return v;\n        }\n    }\n    1\n}\n\nfn fill_align(sw: Swizzle, cols: usize, elem_bytes: usize) -> usize {\n    swizzle_align(sw).max(cp_async_width(cols, elem_bytes) * elem_bytes)\n}\n\nfn tma_dest_align(sw: Swizzle) -> usize {\n    // the box copy faults on an unaligned DESTINATION — NONE still pins 128 B\n    swizzle_align(sw).max(TMA_SLAB_ALIGN)\n}\n".to_string(),
        },

        // ── software-swizzle-shift-row-stride — the shift-derivation axis (A) ──
        KernelRule {
            rule_id: "software-swizzle-shift-row-stride".to_string(),
            gpu_concept: "A SOFTWARE-filled shared-memory slab (cp.async destination XOR / vector Writes) drained by ldmatrix carries an XOR swizzle whose SHIFT must derive from the slab's ROW STRIDE, not default to log2 of the swizzle-atom elements — the default shift IS the row only while a slab row is exactly one atom; a wider row (a 128-element fp16 head-dim row is two 128 B atoms) collapses consecutive rows onto a quarter of the chunk positions. Measured, verbatim (kernel/_stage.py:352-356): \"the default shift is log2(atom elems), which IS the row only while a slab row is exactly one atom. A wider row (a 128-elem fp16 head-dim row is two 128 B atoms) must shift by its own stride or consecutive rows collapse onto a quarter of the chunk positions — the measured 7.8-way ldmatrix conflict at D = 128 that vanishes at D = 64.\" The gate is three-way and byte-identical-preserving (_stage.py:358-362): NONE mode, a row that IS one atom, or a non-power-of-two row (\"where no row bit is extractable\") keep the plain spelling \"so every slab that already drained conflict-free emits byte-identically\"; else the spelling gains the shift — mode@log2(inner_elems). Hardware (TMA) slabs are excluded by construction (_stage.py:357-359): \"the copy engine fixes their permutation, and their descriptor already splits its box down to the atom — they keep pick_swizzle_atom.\" The atom derivation is ONE function consumed by THREE parties — the descriptor build, the box-coordinate split, and the drain's per-slab mode derivation — and disagreement is a deadlock, not a slowdown (_stage.py:331-337): \"a disagreement makes the descriptor's swizzle claim a width its box doesn't have — a TMA copy deadlock.\" The atom itself: \"the widest atom in {128, 64, 32} B that fits and divides the span wins\" (_stage.py:334-336). The transport scoping is named (_stage.py:139-140): \"This is the sm_89 bank-conflict fix: the plain row-major slab leaves the drain 4-way (64 B rows) / 8-way (128 B rows) conflicted.\" Honest NotBenchable (the 7.8-way / 4-way / 8-way numbers are source-reported on CUDA; our box is M3 Metal — the gate is static and unit-testable). Distinct from xor-swizzle-smem-static-index-tables (A — precomputes the XOR transform into static index TABLES for unrolled loops, the TABULATION axis; this derives the swizzle SHIFT parameter itself — tables built per-atom instead of per-row-stride bake exactly this defect), from vectorized-smem-write-no-bank-padding (A — swizzle-NOT-pad as the complement of no-pad-for-vectorized-stores; this supplies the concrete shift parameterization that complement must get right), from smem-pad-transport-gated (this batch — the PAD is the other software-transport conflict fix; hardware-swizzled slabs need neither), and from lds-cluster-cross-warp-phase-not-static-distance (B130 — LDS temporal clustering vs warp phase, a SCHEDULING axis; this is an address-BIT axis). Category A (memory access). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — _stage.py:325-343, :346-362, :135-140. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: the XOR swizzle shift is log2(atom elems) — correct ONLY while a\n// slab row is exactly one swizzle atom. A 128-elem fp16 row spans TWO\n// 128 B atoms, so consecutive rows collapse onto a quarter of the chunk\n// positions: 7.8-way ldmatrix conflict at D = 128 (gone at D = 64).\nconst ATOM_ELEMS_B128: usize = 64; // 128 B / 2 B fp16\n\nfn swizzle_addr_default(row: usize, col: usize) -> usize {\n    let shift = ATOM_ELEMS_B128.ilog2() as usize; // 6 — the DEFAULT\n    let permuted = col ^ (row << shift); // row bits above bit 6 do nothing:\n    row * ATOM_ELEMS_B128 + (permuted & (ATOM_ELEMS_B128 - 1)) // rows alias\n}\n\nfn drain_all(rows: usize, cols: usize) -> usize {\n    let mut reads = 0;\n    for r in 0..rows {\n        for c in 0..cols {\n            let _addr = swizzle_addr_default(r, c);\n            reads += 1; // lanes stack on the same chunks\n        }\n    }\n    reads\n}\n".to_string(),
            opt_pattern: "// optimized: shift = the row's own stride (log2 inner_elems), gated\n// three ways; NONE / one-atom rows / non-pow2 rows keep the plain\n// spelling, so every already-conflict-free slab emits byte-identically.\nfn software_swizzle_mode(inner_elems: usize) -> String {\n    let (atom_elems, mode) = pick_swizzle_atom(inner_elems);\n    let is_pow2 = inner_elems != 0 && (inner_elems & (inner_elems - 1)) == 0;\n    if mode == \"NONE\" || inner_elems == atom_elems || !is_pow2 {\n        return mode.to_string(); // plain spelling: byte-identical back-compat\n    }\n    format!(\"{}@{}\", mode, inner_elems.ilog2()) // shift by the row's own stride\n}\n\nfn pick_swizzle_atom(inner_elems: usize) -> (usize, &'static str) {\n    // widest atom in {128, 64, 32} B that fits and divides the span (fp16)\n    for (wb, mode) in [(128usize, \"B128\"), (64, \"B64\"), (32, \"B32\")] {\n        let we = wb / 2;\n        if we <= inner_elems && inner_elems % we == 0 {\n            return (we, mode);\n        }\n    }\n    (inner_elems, \"NONE\")\n}\n".to_string(),
        },

        // ── companion-slab-ring-slot-sync — the sidecar index duty (A) ──
        KernelRule {
            rule_id: "companion-slab-ring-slot-sync".to_string(),
            gpu_concept: "A COMPANION slab (block scales, per-tensor alpha factors — any sidecar read alongside a primary operand) staged through the SAME depth-D ring as the codes it qualifies must carry the ring-slot ROW OFFSET in its drain index; a bare within-tile coordinate reads slot 0 while the codes read slot s, and a subset of cells is scaled by the wrong block. The source found it live, verbatim (kernel/_atom.py:411-420): \"The block-scaled cell's two scale slabs are copies riding the same ring as their codes, so they carry the slot row like any other copied operand — one row per slot, the same count, so the data slab's own offset serves. Without it the scales are read from slot 0 while the codes come from slot s, and a subset of cells is scaled by the wrong block (found live: most outputs exact, a minority off by a factor of 2-3).\" The wrongness survives BOTH standard checks: source review (\"invisible in the emitted source\") and aggregate parity (most outputs exact) — only a per-cell/subset oracle or this structural rule catches it. The counter-case is deliberate, not an oversight (_atom.py:411-413): \"The W4A16 drain's scale slab is COMPUTE-FILLED and single-buffer, so its row is the bare within-tile coord\" — the rule keys on HOW the companion is produced, not on what it contains. Fix-space: a copied (ring-riding) companion carries scale_row = slot_offset + local_coord; a compute-filled single-buffer companion keeps the bare coordinate; and companion fragments are named PER CHANNEL exactly as data fragments are — \"with one name for every channel the second channel would read the first channel's scales, which is wrong by a per-block factor and invisible in the emitted source\" (_atom.py:386-389). The same channel-collision class reaches the epilogue: \"Folding them all into a single product would apply one channel's per-tensor scale to the other, which is wrong by a scalar and invisible in the emitted source — only numerical parity catches it\" (_atom.py:1172-1175). Honest NotBenchable (the repro is a CUDA epilogue parity harness; the structural gate is backend-neutral and unit-testable). Distinct from quant-group-scale-fetch-gating (B92 — WHEN to fetch scales per quant group, a fetch-frequency decision; this is ring-slot INDEX derivation for already-staged scale slabs), from smem-slot-role-reversal-needs-barrier (slot-ROLE reversal ordering/synchronization; this is index arithmetic with no barrier semantics), from register-double-buffer-operand-pipeline (A — the ring itself; this is the sidecar's index duty INSIDE it), and from block-quant-weight-pad-never-extends-activations (B129 — weight-stride format padding for block-quantized layouts; this is the block-scale READ path under double buffering). Category A (memory access). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — _atom.py:386-395, :405-425, :1170-1176. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: the scale slab rides the same depth-2 ring as the codes, but its\n// drain index is the bare within-tile row — slot 0 is read while the codes\n// come from slot s. Most outputs check out; a minority is off by 2-3x.\nconst BLOCK_K: usize = 128;\n\nstruct Slab {\n    bytes: Vec<u8>,\n}\n\nfn drain_cell(ring: &[Slab; 2], slot: usize, row: usize, col: usize) -> f32 {\n    let codes = load_codes(&ring[slot], row, col);\n    let scale = load_scale(&ring[0], row, col / BLOCK_K); // BUG: bare row, slot 0\n    codes * scale\n}\n\nfn load_codes(s: &Slab, row: usize, col: usize) -> f32 {\n    0.0 + row as f32 + col as f32 + s.bytes.len() as f32 * 0.0\n}\n\nfn load_scale(s: &Slab, row: usize, col: usize) -> f32 {\n    1.0 + row as f32 * 0.0 + col as f32 * 0.0 + s.bytes.len() as f32 * 0.0\n}\n".to_string(),
            opt_pattern: "// optimized: a COPIED (ring-riding) companion carries the slot row like\n// any other copied operand — scale_row = slot_offset + local_coord; a\n// compute-FILLED single-buffer companion keeps the bare coordinate.\nconst BLOCK_K: usize = 128;\nconst ROWS_PER_SLOT: usize = 16;\n\nstruct Slab {\n    bytes: Vec<u8>,\n}\n\nenum Companion {\n    Copied { slab_idx: usize }, // rides the ring: carries the slot offset\n    ComputeFilled,              // single-buffer: bare within-tile coord\n}\n\nfn drain_cell(comp: &Companion, ring: &[Slab; 2], slot: usize, row: usize, col: usize) -> f32 {\n    let codes = load_codes(&ring[slot], row, col);\n    let scale_row = match comp {\n        Companion::Copied { .. } => slot * ROWS_PER_SLOT + row, // the slot row rides along\n        Companion::ComputeFilled => row,                        // deliberately bare\n    };\n    let scale = load_scale(&ring[0], scale_row, col / BLOCK_K);\n    // fragments are named PER CHANNEL — one name per channel, or channel 1\n    // silently reads channel 0's scales (wrong by a per-block factor).\n    codes * scale\n}\n\nfn load_codes(s: &Slab, row: usize, col: usize) -> f32 {\n    row as f32 + col as f32 + s.bytes.len() as f32 * 0.0\n}\n\nfn load_scale(s: &Slab, row: usize, col: usize) -> f32 {\n    1.0 + row as f32 * 0.0 + col as f32 * 0.0 + s.bytes.len() as f32 * 0.0\n}\n".to_string(),
        },

        // ── ptxas-recoalesces-scalar-runs-wash — the vectorization wash (A) ──
        KernelRule {
            rule_id: "ptxas-recoalesces-scalar-runs-wash".to_string(),
            gpu_concept: "Hand-vectorizing regular stride-1 scalar-load runs from one buffer is a WASH on NVIDIA toolchains: ptxas coalesces the runs into wide LDS.128 / LDG.128 transactions itself once alignment is known, so the vectorized and scalar source forms compile to identical SASS at every deployable opt level — the toggle measured 0% at every -O and stays zero even on a deliberately load-bound tile. The article's measurement (§Vectorized Loads, verified fetch): \"Toggling vectorization on and off measures 0% difference at every -O level ... The only flag that makes the pass change the machine code is -Xptxas -O0.\" The repo encodes the counter as engineering doctrine — the pass exists for IR legibility and is deliberately NOT a search dimension, verbatim (kernel/050_vectorize_loads.py:34-38): \"This is an IR-legibility pass, not a perf lever: ptxas coalesces scalar ld.shared runs once alignment is known, so the vectorized and scalar source forms compile to identical SASS at every deployable opt level. VECTORIZE_LOADS is therefore not a search dimension — only True is enumerated.\" (EMMY_VECTORIZE_LOADS=0 is a manual override; the knob convention is repo-wide — search/space.py:22-24: \"boolean codegen policies recorded on the kernel op (idempotence + env override), on by default and not search dimensions (hints=(True,)).\") The escape arm is REAL and narrow — irregular kernels: \"Nvcc does fail to coalesce on less regular kernels (unprovable alignment, gapped strides)\" — and then a static alignment proof is mandatory: \"n=2 fp16 is NOT a freebie despite __half2's 4-byte type alignment — an odd-element offset still misses the alignment and faults with CUDA_ERROR_MISALIGNED_ADDRESS\" (050:176-179). Stores fold into the same rule (080_vectorize_stores.py is the symmetric pass). Bench-budget corollary: do NOT spend autotuner or league bench cycles toggling hand-vectorization on regular kernels — spend them on the regularity the coalescer needs (alignment, contiguity). Honest NotBenchable (no ptxas/CUDA toolchain on this box; wash numbers source-reported on RTX 5090 plus the repo's SASS claim). Distinct from vector-width-pow2-sweep (K — vectorization WIDTH as an autotune dimension; they COMPOSE with a silicon scope split: the sweep stays live where the backend does NOT recoalesce — Metal/AMD/WGSL — or where the fold is illegal so manual structuring is the only route; on ptxas the on/off fold is a wash and must not consume a search dimension), from coalesced-row-read / matvec-coalesce / layout-permute-for-coalescing (A — those CREATE the consecutive regularity this rule then refuses to hand-optimize: layout first, hand-fold never), from stride-align-vectorization-key (L — the alignment KEY that decides whether the escape arm's proof can pass at all), and from vectorized-pack-load (A — PACKING values into a vector TYPE for compute, not memory-transaction folding). Category A (memory access). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — 050_vectorize_loads.py:34-38, :170-185; 080_vectorize_stores.py; search/space.py:22-24, :153-160. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: hand-folding scalar loads into a wide load to \"help\" the\n// backend, and an autotuner dimension toggling it — on ptxas both arms\n// compile to the SAME SASS, so the dimension is pure bench budget burned.\n#[derive(Clone, Copy)]\nenum LoadForm {\n    Scalar,\n    Vectorized,\n}\n\nfn bench_vectorization(form: LoadForm, trials: usize) -> f32 {\n    let mut total = 0.0f32;\n    for _ in 0..trials {\n        total += run_kernel(&form); // 0.00 delta at every deployable -O\n    }\n    total / trials as f32\n}\n\nfn run_kernel(form: &LoadForm) -> f32 {\n    match form {\n        LoadForm::Scalar => 1.0,\n        LoadForm::Vectorized => 1.0, // identical SASS: identical time\n    }\n}\n".to_string(),
            opt_pattern: "// optimized: keep the legibility fold OUT of the search space; spend the\n// bench on the regularity the coalescer needs, and hand-fold only with a\n// static alignment proof on an irregular kernel.\n#[derive(Clone, Copy)]\nenum LoadForm {\n    Scalar,     // default: ptxas recoalesces the run\n    Vectorized, // escape arm ONLY: irregular strides/gaps, proof required\n}\n\nfn alignment_proof_ok(offset: usize, elems: usize, elem_bytes: usize) -> bool {\n    // every free coefficient AND the literal anchor must be multiples of n\n    let width_bytes = elems * elem_bytes;\n    width_bytes > 0 && offset % width_bytes == 0\n}\n\nfn choose_form(is_regular: bool, offset: usize, elems: usize, elem_bytes: usize) -> LoadForm {\n    match is_regular {\n        true => LoadForm::Scalar, // not a search dimension — ptxas owns it\n        false => {\n            if alignment_proof_ok(offset, elems, elem_bytes) {\n                LoadForm::Vectorized\n            } else {\n                LoadForm::Scalar // unprovable alignment: the fold would FAULT\n            }\n        }\n    }\n}\n".to_string(),
        },

        // ── ptxas-reschedules-load-order-wash — the scheduling wash (A) ──
        KernelRule {
            rule_id: "ptxas-reschedules-load-order-wash".to_string(),
            gpu_concept: "Hand-sinking or hoisting SYNCHRONOUS loads to interleave them with their consumer FMAs is a wash at every deployable opt level — ptxas owns instruction scheduling and reschedules both source forms to nearly the same SASS; only -Xptxas -O0 preserves source order, and that level is for debugging, never a deployment claim. The repo's verdict, verbatim (kernel/095_interleave_loads.py:23-26): \"Observed impact: an IR-legibility transform; ptxas reschedules both forms to nearly the same SASS at deployable opt levels, so INTERLEAVE_LOADS is not a search dimension — only True is enumerated.\" (EMMY_INTERLEAVE_LOADS=0 manual override; the hints=(True,) convention, search/space.py:22-24.) The pass is semantics- and order-safe by construction: \"Non-Load stmts keep their relative order — no semantic reorder of Assigns / Accums\" (095:20-21) and \"Idempotent — a body already in interleaved form is a no-op\" (095:28). The article's measured confirmation (§Load Interleaving): \"load/compute interleaving is a wash at every deployable -O level. Only -Xptxas -O0 preserves the source order.\" The scope boundary that keeps the rule honest: the wash covers SYNCHRONOUS load ORDER inside straight-line code only. ASYNC issue-site placement — where a cp.async / TMA copy task enters the instruction stream relative to tile matmuls — is a REAL overlap decision the backend does not make for you (owned by interleave-loads-between-tile-matmuls, D), and reassociation SEMANTICS are untouched (ptxas reordering loads never reorders floating-point accumulation chains — interleave-independent-accumulators-only, E, still governs when YOU reorder accumulators). Honest NotBenchable (no ptxas on this box; wash is source-reported RTX 5090 plus the repo's SASS claim). Distinct from interleave-loads-between-tile-matmuls (D — ASYNC load-task injection BETWEEN tile matmuls, an overlap-mechanism decision; this is synchronous ORDER inside one straight-line block, which the backend owns), from interleave-independent-accumulators-only (E — reassociation semantics under parity gates, a correctness guard on YOUR reordering, not a scheduling-perf claim), from independent-accumulator-chains-hide-load-latency-at-capped-occupancy (A — multiple accumulator CHAINS as a latency-hiding STRUCTURE; that survives because it changes the dataflow graph, not the statement order), and from ptxas-recoalesces-scalar-runs-wash (this batch — the memory-TRANSACTION axis of the same compiler-owns-it verdict). Category A (memory access). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — 095_interleave_loads.py:20-28; search/space.py:22-24, :161-168. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: hand-hoisting every smem load, then the FMA block — scheduling\n// by hand for latency, and benchmarking the two orders as an autotune\n// pair. ptxas reschedules both to nearly the same SASS: the pair is a wash.\n#[derive(Clone, Copy)]\nenum LoadOrder {\n    HoistedAll,\n    Interleaved,\n}\n\nfn bench_schedule(order: LoadOrder, trials: usize) -> f32 {\n    let mut total = 0.0f32;\n    for _ in 0..trials {\n        total += run(&order);\n    }\n    total / trials as f32\n}\n\nfn run(order: &LoadOrder) -> f32 {\n    match order {\n        LoadOrder::HoistedAll => 1.0,\n        LoadOrder::Interleaved => 1.0, // identical SASS at deployable -O\n    }\n}\n".to_string(),
            opt_pattern: "// optimized: keep source order legible (loads next to first use is fine,\n// but no bench rides on it); spend the effort on structures ptxas CANNOT\n// invent — async issue-site placement and accumulator-chain dataflow.\n#[derive(Clone, Copy)]\nenum Effort {\n    SyncLoadOrder,   // wash: backend-owned, never a search dimension\n    AsyncIssueSites, // REAL: where cp.async/TMA tasks enter the stream\n    AccumulatorChains, // REAL: dataflow-level latency hiding\n}\n\nfn plan(opt: Effort) -> &'static str {\n    match opt {\n        Effort::SyncLoadOrder => \"legibility only — no bench dimension\",\n        Effort::AsyncIssueSites => \"interleave-loads-between-tile-matmuls\",\n        Effort::AccumulatorChains => \"independent-accumulator-chains rule\",\n    }\n}\n".to_string(),
        },

        // ── smem-pad-transport-gated — the bank-pad transport gate (A) ──
        KernelRule {
            rule_id: "smem-pad-transport-gated".to_string(),
            gpu_concept: "A shared-memory bank-conflict pad is TRANSPORT-GATED, and the gate has two halves. First the TRANSPORT: under TMA a pad is dead code — the hardware descriptor swizzle permutes the box deposit, so there is no conflict left to pad away; under cp.async the pad is live. The repo's constant encodes it (ir/address.py:19-28, verbatim): \"a dense power-of-two byte row lands every 4-row group in the same bank quartet (4-way conflicts measured by the lane→bank oracle on both the k16 convert drain and the k32 repack drain, either B orientation). 16 extra bytes per row breaks the stride while keeping every 16 B cp.async chunk aligned ... Derived, not tuned — the bank-quartet aliasing argument. cp.async only: a TMA box deposit is dense (its byte slab stays unpadded and eats the measured conflicts).\" Second the GRANULARITY: pad one full transfer-granularity unit per row (16 B — breaks the bank-quartet stride while every cp.async chunk stays aligned), or for an already-VECTORIZED conflicted read deliberately pad +1 element to BREAK alignment and de-vectorize the read — the article's measured arm (§Shared-Memory Padding): \"the generated read drops from a conflicted float4 to a conflict-free scalar load — the pad breaks 16-byte alignment, and a conflict-free scalar beats a serialized vector four times over\" (3.7x on the 26x4 tile at stride 128, RTX 5090). The integrity half is a one-source-of-truth contract between fill and drain (_atom.py:910-912): \"pad is the bits slab's row pad in bytes — BYTE_SLAB_PAD under cp.async, whose fill wants the bank spread, and zero under TMA, whose box deposits dense. The drain reads it back off Operand.pad_cols, so the two cannot disagree.\" The descriptor-side replacement on the TMA arm is the _SWIZZLE table (backend/cuda/_tma.py:56-57: NONE 0 / B32 1 / B64 2 / B128 3). The broadcast half of the axis: same-address lane reads are FREE — hardware broadcast — so a conflict needs DIFFERENT addresses on one bank, which is why the article's conflict visualizer colors cells by ADDRESS, not by lane. Honest NotBenchable (no TMA on Apple silicon, no cp.async; the 3.7x / 4-way numbers are source-reported RTX 5090 and 4090-verifiable — cp.async is sm_80+, Ada included; the lane-to-bank oracle is portable as a static analysis). Distinct from vectorized-smem-write-no-bank-padding (A — default-layout VECTORIZED STORES need no pad because line-sized stores distribute across banks, plus a scalar-staging rider; this owns CONFLICTED READS under an explicit transport key with a granularity fork — they tile: that rule's know-which-staging-arm boundary is exactly the question this answers), from xor-swizzle-smem-static-index-tables (A — the explicit software swizzle, the third arm; under TMA the descriptor swizzle replaces BOTH pad and tables), from software-swizzle-shift-row-stride (this batch — the shift parameterization the software-swizzle arm must get right), and from lds-cluster-cross-warp-phase-not-static-distance (B130 — LDS temporal clustering, a scheduling axis, not a bank-address axis). Category A (memory access). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — ir/address.py:15-30; _atom.py:905-912; backend/cuda/_tma.py:55-60. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: one padding policy for every transport — a +N pad applied under\n// TMA where the descriptor already swizzles (dead bytes), or no pad under\n// cp.async where the dense power-of-two row lands 4-way conflicted.\nstruct Slab {\n    row_bytes: usize, // power of two: every 4 rows hit one bank quartet\n    pad_bytes: usize, // 0 everywhere: \"pads are dead\" / \"pads are free\"\n}\n\nfn row_stride(s: &Slab) -> usize {\n    s.row_bytes + s.pad_bytes\n}\n\nfn bank_of(addr: usize) -> usize {\n    (addr / 4) % 32\n}\n\nfn conflicted_lanes(s: &Slab, lane_rows: [usize; 4]) -> usize {\n    let stride = row_stride(s);\n    let mut distinct = 1usize;\n    let first = bank_of(lane_rows[0] * stride);\n    let mut i = 1;\n    while i < lane_rows.len() {\n        if bank_of(lane_rows[i] * stride) != first {\n            distinct += 1;\n        }\n        i += 1;\n    }\n    5 - distinct // 4-way: all four lanes in one quartet under a dense row\n}\n".to_string(),
            opt_pattern: "// optimized: transport-gated pad + granularity fork, one source of truth\n// shared by fill and drain so the two cannot disagree.\nconst BYTE_SLAB_PAD: usize = 16; // cp.async only; TMA deposits dense\n\n#[derive(Clone, Copy, PartialEq)]\nenum Transport {\n    Tma,     // descriptor swizzle: pad is dead code\n    CpAsync, // software fill: pad is live\n}\n\nstruct Slab {\n    row_bytes: usize,\n    transport: Transport,\n}\n\nimpl Slab {\n    fn pad_bytes(&self) -> usize {\n        match self.transport {\n            // \"zero under TMA, whose box deposits dense\"\n            Transport::Tma => 0,\n            // 16 B: breaks the bank-quartet stride, chunks stay aligned\n            Transport::CpAsync => BYTE_SLAB_PAD,\n        }\n    }\n\n    fn row_stride(&self) -> usize {\n        self.row_bytes + self.pad_bytes()\n    }\n}\n\n#[derive(Clone, Copy)]\nenum PadGranularity {\n    ChunkAligned, // +16 B per row: keeps every cp.async chunk 16 B-aligned\n    Devectorize,  // +1 element: a conflicted float4 becomes a free scalar\n}\n\nfn drain_pad(s: &Slab) -> usize {\n    // the drain reads the pad back off the operand — never re-derives it\n    s.pad_bytes()\n}\n".to_string(),
        },

        // ── split-k-atomic-arm-legality — the semantic legality fork (E) ──
        KernelRule {
            rule_id: "split-k-atomic-arm-legality".to_string(),
            gpu_concept: "A cross-CTA split-K reduction's DIRECT atomicAdd arm is SEMANTICALLY illegal for whole carrier families regardless of shape — legality is a four-condition conjunction, not a tuning knob: (1) ONE state component — \"atomicAdd folds a scalar; a twisted carrier's (maximum, denominator, ...) tuple has no atomic instruction at all\"; (2) an ADDITIVE monoid — \"The emitted instruction IS atomicAdd — a max carrier's partials would be SUMMED, silently wrong\"; (3) an output the partials can round into once per CTA — F16/BF16 destinations \"round once per CTA; the deferred finalize instead combines f32 carrier state and rounds once at the output boundary\"; (4) a projection that DISTRIBUTES over the add — \"The atomic arm applies the epilogue per partition, before the combine, so anything but a linear-homogeneous map mis-scales each CTA's contribution\" (tile/_split.py:96-114, verbatim). Ordering is load-bearing: \"Storage is asked BEFORE the projection: a narrowing store spells its rounding as a conversion in that same epilogue ... so both refuse a low-precision output and the storage reason is the one that names why\" (:105-108). Fail-safety: the offer's read is the superset, so the only divergence is OVER-refusal — \"safe, since a withheld atomic row leaves the deferred finalize, never a crash\" (:110-114). Every refusal NAMES the alternative (the deferred f32-workspace finalize, REDUCE=g<n>k) — never a bare false. The admission arm: \"A cross-CTA split needs a STATIC reduce axis its width divides evenly — the sigma-reindex reconstructs an absolute k from ksplit*(K/w) + kslice, which is a bijection only when the extent is known and w divides it. Total over a symbolic axis rather than raising ... so the catalog drops the width and a pin reports the reason\" (:61-67). The article covers split-K's PERFORMANCE fork only (7.1x skinny, loss on square); the legality fork is the repo's contribution and is unit-testable anywhere (monoid/projection classifiers are pure functions). Distinct from target-tile-split-k-deterministic-two-dispatch (E — the two-dispatch STRUCTURE for determinism + quant-boundary alignment + transform placement, a CONTRACT axis; this is the atomic arm's semantic LEGALITY, including the low-precision rounding fork determinism does not own), from split-k-two-pass-attention-decode-long-context (F — the attention softmax two-pass whose carrier is (max, sum): exactly condition 2's refusal — the atomic arm would SILENTLY sum it), from streamk-starved-tile-grid-dispatch (A — occupancy admission + owned-tile flush for stream-K, an orthogonal axis), from multiplexed-grid-axis-partition-modes-exclusive (B130 — two partition MODES claiming one grid axis; this is one mode's internal legality), and from splitk-atomic-free-contention-threshold (this batch — the PERF fork between the same two arms: legality decides WHETHER the atomic arm may run, contention decides WHEN it should). Category E (parallelism). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — tile/_split.py:55-134. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: pick atomicAdd vs the deferred finalize by shape alone. The\n// carrier here is (max, denominator) — softmax-style — and the projection\n// applies a per-row scale. Both are illegal: the atomic would SUM a max\n// carrier and mis-scale per-CTA contributions. Silently wrong.\n#[derive(Clone, Copy)]\nenum Combine {\n    AtomicAdd,\n    DeferredFinalize,\n}\n\n#[derive(Clone, Copy)]\nstruct Carrier {\n    maximum: f32,\n    denominator: f32, // TWO state components: no atomic instruction exists\n}\n\nfn choose_by_shape(splits: usize, mn: usize) -> Combine {\n    if splits * mn < 1_000_000 {\n        Combine::AtomicAdd // cheap fast path — legality never asked\n    } else {\n        Combine::DeferredFinalize\n    }\n}\n\nfn fold_unchecked(parts: &[Carrier]) -> Carrier {\n    let mut acc = Carrier {\n        maximum: 0.0,\n        denominator: 0.0,\n    };\n    for p in parts {\n        acc.maximum += p.maximum; // WRONG: maxes must max, not sum\n        acc.denominator += p.denominator;\n    }\n    acc\n}\n".to_string(),
            opt_pattern: "// optimized: a four-condition legality gate asks BEFORE the fork; every\n// refusal names the deferred finalize as the alternative.\n#[derive(Clone, Copy)]\nenum Combine {\n    AtomicAdd,\n    DeferredFinalize,\n}\n\n#[derive(Clone, Copy)]\nstruct Legality {\n    one_state_component: bool,\n    additive_monoid: bool,\n    output_rounds_once: bool,\n    projection_distributes: bool,\n}\n\nfn choose(l: &Legality) -> Result<Combine, &'static str> {\n    match (\n        l.one_state_component,\n        l.additive_monoid,\n        l.output_rounds_once,\n        l.projection_distributes,\n    ) {\n        (true, true, true, true) => Ok(Combine::AtomicAdd),\n        // storage is asked BEFORE projection: its reason names the fork\n        (true, true, false, _) => Err(\"low-precision output rounds per CTA: use REDUCE=g<n>k\"),\n        (false, _, _, _) => Err(\"atomicAdd folds ONE scalar: use the deferred finalize\"),\n        (_, false, _, _) => Err(\"partials of a max carrier would be SUMMED: use the finalize\"),\n        (_, _, _, false) => Err(\"epilogue must distribute over the add: use the finalize\"),\n    }\n}\n".to_string(),
        },

        // ── setmaxnreg-fit-gate-elected-arrive — the warp-spec handshake gates (E) ──
        KernelRule {
            rule_id: "setmaxnreg-fit-gate-elected-arrive".to_string(),
            gpu_concept: "A warp-specialized kernel's register redistribution and producer/consumer handshake carry three gates the recipe presentations skip. (1) FIT GATE: setmaxnreg.inc claims from the SM's per-CTA register pool, so emit the .dec/.inc pair only when the raised total provably fits the register file — the source's constants and check, verbatim (kernel/_stage.py:909-917): \"producers drop to the 24-register floor, consumers raise to 240. setmaxnreg.inc claims from the SM's per-CTA pool, so emit the pair only when the raised total provably fits the 64K-register file — past that envelope the split still runs, just without redistribution\" with _PRODUCER_REGS = 24, _CONSUMER_REGS = 240, _SM_REGFILE = 65536 and the gate setmaxnreg = _CONSUMER_REGS * block_threads + _PRODUCER_REGS * aux_threads <= _SM_REGFILE (:967). The article presents the pair as a free recipe step (producer setmaxnreg.dec 24 / consumers 240); the repo gates it on register-file arithmetic. (2) NAMED BAND BARRIER: the consumer band synchronizes with a named bar.sync over the compute band ONLY — \"a CTA-wide __syncthreads() is UB on the divergent role branch\" (:944-945). (3) ONE ELECTED ARRIVE: the empty-slot mbarrier counts 1, not block_threads — \"the elected release rides the barrier's happens-before, so the empty mbarrier counts 1, not block_threads (one smem atomic per chunk instead of one per thread)\", and \"The arrive helper carries the fence.proxy.async that orders the band's GENERIC slab reads before the producer's next ASYNC box-copy into the slot\" (:945-950). Election rider: mbarrier init in a split kernel is RAW-tid-elected, not the transport's wrapped election — \"the transport's wrapped linear_tid == 0 election would match one compute AND one aux thread here\" (:956-959) — election semantics change when the block grows a producer tail band. Scope: sm_90+ only (\"every warp-spec kernel is TMA-gated\", :909-910). RIDER (Batch 138, cloudrift-ai/emmy @ bdd26c53 + the FlashAttention articles -- the ASYNC-MMA half of the admission predicate): the scope sharpens from TMA-gated to TMA AND ASYNC-MMA-gated -- \"Consumer Blackwell (sm_120) has TMA, but no wgmma: its tensor core is the synchronous mma.sync. Warp specialization without async MMA is a pessimization for flash attention\", measured \"Warp specialization (213 vs 206µs) ... Dedicating a producer warp slows down the overall pipeline\" (the blog Part 2, Refused Optimizations + the FA-3/4 sections -- quote-authority, fetched full-text 2026-09-09); FA-4's tcgen05/TMEM/2-CTA MMA is sm_100-only (\"None of that silicon is present on sm_120\"), and the fresh tip pins the scheduler half (\"warp specialization drives the TMA transport only (scheduler legality)\", _stage.py:1416) -- TMA without an asynchronous tensor instruction to overlap leaves the producer warp nothing worth dedicating. Honest NotBenchable (no Hopper/Blackwell in this workspace; the fit-gate arithmetic is unit-testable). Distinct from plane-specialization-load-compute-role-split (E — the role-SPLIT structure itself: comptime partition + warp-uniform branch; this is the post-split register legality + release handshake — they compose, neither subsumes), from tma-single-issuer-bulk-tile (A, B130 — the TMA issue-side lifecycle + barrier-reuse spacing; this is the consumer-to-producer RELEASE side), from no-blocking-sync-in-async-pipeline (host-side queue sync, a different layer), and from barrier-after-async-mma-before-staged-tile-reuse (overwrite ordering before tile reuse; this is divergent-branch barrier LEGALITY). Category E (parallelism). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — _stage.py:908-970. Batch 137 / Plan 116. RIDER (Batch 149, the sm_89 counterpart fact -- riir-ai B933 §3/§5/§6, measured envelope): consumer Ada has NO setmaxnreg -- warp-specialized splits share ONE register allocation, so on sm_89 a producer/consumer split buys issue-slot separation ONLY, never register headroom. The envelope: a 32x32-warp-tile body's accumulators alone are 64 regs/thread (dh[2][4][4] i32 + o[2][4][4] f32) + ~64 decode/fragment working set = exactly the 512x128 = 65,536-reg file; B933 §5's bounded disposition prices the entire warp-spec arm at <= the 7.3% decode share it could take off the consumer chain (staging already cp.async; the register redistribution this rule's fit gate governs does not exist on the die -- the sm_90+ escape hatch itself is the thing consumer silicon lacks). The rule's sm_90+ scope is sharpened from the consumer side: the same probe series measured the TMA machinery this rule composes with as PHYSICALLY ABSENT on consumer silicon (the Batch-148 mma-fragment rider carries the probe: error 715 / cluster-only bulk / driver-vs-runtime attribute split). See spill-fragility-law-accumulator-regcap-cliff (Batch 149) for the cap-cliff law that prices every remaining register decision on such dies. RIDER (Batch 272, the MIRROR FENCE face -- generic WRITES before async-proxy READ, dphnAI/sonar @ 927f3262): the host rule owns the fence direction where the elected arrive's `fence.proxy.async` orders the band's GENERIC slab READS before the producer's next ASYNC box-copy INTO the slot (consumer-to-producer release); the paired PCIe all-reduce's TMA staging tile owns the OPPOSITE direction, same primitive -- the leader's outbound `cp.async.bulk.global.shared::cta` READS the shared staging tile, so every generic WRITER must fence before the leader issues the async read: 'the oldest of two shared tiles is no longer read by the async proxy before any generic writer reuses that tile' guards tile REUSE (a `cp.async.bulk.wait_group.read 1` + `fence.proxy.async.shared::cta` pair before the writers refill the oldest tile), and a second plain 'Fence every writer before the leader can issue the async read. / fence.proxy.async.shared::cta;' sits between the fill loop and the issue (csrc/pcie_pull_all_reduce.cu paired_bulk_payload, verbatim comments at the pin). The mirror is complete: B137 = generic reads before async write; this = generic writes before async read -- the `fence.proxy.async.shared::cta` primitive is the SAME fence because the ASYNC PROXY is the other party in both directions (its cached view of shared memory is what the fence invalidates). DOUBLE-BUFFERED COUNTERPART: the wait_group.read 1 + (index & 1) tile pairing IS the double-buffering discipline -- a fence before EVERY fill would stall on the tile still in flight; the reuse guard fences only the OLDEST tile, exactly when its in-flight read has drained. Verified: paired_bulk_payload at the pin 927f3262 (clone .raw/b272/sonar, worktree .pin; PR head f653ba4e at mine time). Batch 272 rider / Plan 276 / Research 308.".to_string(),
            ref_shape: "// naive: paste the warp-spec recipe verbatim — unconditional setmaxnreg,\n// a CTA-wide barrier inside the divergent branch, everyone arrives.\nstruct WarpSpec {\n    block_threads: u32, // consumer band\n    aux_threads: u32,   // producer band (the tail band)\n}\n\nstruct Sync {\n    barrier: Barrier,\n    empty_count: u32,\n}\n\n#[derive(Clone, Copy)]\nenum Barrier {\n    CtaWide,\n    Named(u32),\n}\n\nfn producer_consumer_sync(k: &WarpSpec, regfile: u32) -> Sync {\n    // (a) no fit check: 240*n_consumers + 24*n_producers may exceed regfile\n    let raised = 240 * k.block_threads + 24 * k.aux_threads;\n    if raised > regfile {\n        // nothing changes — the pair was emitted unconditionally anyway\n    }\n    Sync {\n        barrier: Barrier::CtaWide,   // (b) UB on the divergent role branch\n        empty_count: k.block_threads, // (c) every thread arrives: 128 atomics\n    }\n}\n".to_string(),
            opt_pattern: "// optimized: fit-gated register redistribution, named band barrier, one\n// elected arrive carrying the async fence.\nconst PRODUCER_REGS: u32 = 24;\nconst CONSUMER_REGS: u32 = 240;\nconst SM_REGFILE: u32 = 65_536;\n\nstruct WarpSpec {\n    block_threads: u32, // consumer band\n    aux_threads: u32,   // producer band (the tail band)\n}\n\nstruct Sync {\n    redistribute: bool,\n    barrier: Barrier,\n    empty_count: u32,\n    fence_async: bool,\n}\n\n#[derive(Clone, Copy)]\nenum Barrier {\n    CtaWide,\n    Named(u32),\n}\n\nfn setmaxnreg_fits(k: &WarpSpec) -> bool {\n    CONSUMER_REGS * k.block_threads + PRODUCER_REGS * k.aux_threads <= SM_REGFILE\n}\n\nfn producer_consumer_sync(k: &WarpSpec) -> Sync {\n    Sync {\n        redistribute: setmaxnreg_fits(k), // past the envelope: split still runs\n        barrier: Barrier::Named(1),       // compute band ONLY (its thread count)\n        empty_count: 1,                   // ONE elected arrive per chunk\n        fence_async: true,                // fence.proxy.async before the next copy\n    }\n}\n\nfn init_mbarriers_elected(tid: u32) -> bool {\n    // RAW tid == 0, not the wrapped linear_tid election: with a producer\n    // tail band the wrapped election matches one compute AND one aux thread\n    tid == 0\n}\n".to_string(),
        },

        // ── splitk-width-shape-need-gate — the two-floor width predicate (E) ──
        KernelRule {
            rule_id: "splitk-width-shape-need-gate".to_string(),
            gpu_concept: "The split-K WIDTH a shape justifies is needed = max(2*SM/free_ctas, K/sqrt(M*N), 1) with free_ctas = free_prod/area — a TWO-FLOOR predicate in which grid fullness ALONE systematically under-splits: K-heaviness (K much greater than sqrt(M*N)) justifies a split even at a full grid, because a long reduction per output tile parallelizes across the split CTAs even when the free dims already fill the machine. The source's measured mispricing, verbatim (search/features.py:679-683): \"The occupancy-only needed mispriced exactly (b): mlp_down (M=512, N=4096, K=14336) has free_ctas alone saturating the SMs, so it credited ZERO split and ranked the winning g8k golden ~9000-deep. k_ext / sqrt(free_prod) is the K-per-output-linear-dim heaviness (config-independent; ~1 for a square / balanced GEMM, large only when K >> sqrt(M*N)) — a second floor on the split the shape justifies.\" The excess side is pure waste (:666-667): \"Split-K beyond what occupancy needs is pure atomic/combine waste\" — and the paired log2 features encode both directions (:687-697), the deficit side existing because \"split-K had only penalties (D_splitk_le2 / D_splitk_excess), never a reward when justified\". Article corroboration: split-K is \"a loss on the 2048-cubed square — the grid already fills the GPU\" yet \"a 7.1x win\" at 128x128x16384, with SPLITK=16/32 landing 27/25 us (an 11x swing) — the same two-floor shape on real hardware. Worked league-relevant example: an LLM down-projection GEMM (M=512, N=4096, K=14336) on a 128-SM Ada part: occ_need = 2*128/128 = 2 but kheavy_need = 14336/sqrt(512*4096) ~ 9.9, so needed ~ 10 — occupancy-only reasoning says no split where the shape wants ~10-way. Admission preconditions: a STATIC K extent whose width divides exactly (tile/_split.py:61-71). Honest split of the claim: the gate is pure arithmetic — unit-testable anywhere (assert mlp_down yields needed ~ 9.9 and a square yields needed == 1); the OUTCOME numbers (7.1x, 11x) are source-reported RTX 5090 — NotBenchable here, 4090-verifiable (cp.async-era GEMM). Distinct from streamk-starved-tile-grid-dispatch (A — gates on grid STARVATION (ntiles < 8*nsm) into persistent stream-K; the full-grid K-heavy arm is exactly what the starvation predicate cannot see), from split-k-two-pass-attention-decode-long-context (F — the attention softmax accumulation crossover by context length, not a GEMM width gate), from target-tile-split-k-deterministic-two-dispatch (E — the two-dispatch STRUCTURE for determinism; this supplies the WIDTH that structure should use), and from splitk-atomic-free-contention-threshold (this batch — the epilogue fork for the chosen split; this is the gate that sizes the split in the first place). Category E (parallelism). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — search/features.py:665-697; tile/_split.py:61-71. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: split-K width from grid fullness alone — if the tiles already\n// cover the SMs, never split. On a K-heavy shape the grid IS full and the\n// reduction is still the bottleneck: the winning 8-way split ranks ~9000th.\nfn needed_by_occupancy_only(free_ctas: f32, sm_count: f32) -> u32 {\n    let occ_need = 2.0 * sm_count / free_ctas.max(1.0);\n    occ_need.max(1.0) as u32\n}\n\nfn pick_split(m: usize, n: usize, k: usize, sm_count: usize, tile: usize) -> u32 {\n    let free_prod = (m * n) as f32;\n    let area = (tile * tile) as f32;\n    let free_ctas = free_prod / area;\n    let _ = k; // K never asked: the K-heavy floor does not exist here\n    needed_by_occupancy_only(free_ctas, sm_count as f32)\n}\n".to_string(),
            opt_pattern: "// optimized: two floors — occupancy AND K-heaviness — plus the excess\n// penalty. mlp_down (512, 4096, 14336) on 128 SMs: occ 2, kheavy ~9.9.\nfn needed(free_prod: f32, area: f32, sm_count: f32, k_ext: usize) -> f32 {\n    let free_ctas = free_prod / area;\n    let occ_need = 2.0 * sm_count / free_ctas.max(1.0);\n    let kheavy_need = if k_ext > 0 {\n        k_ext as f32 / free_prod.max(1.0).sqrt()\n    } else {\n        1.0\n    };\n    occ_need.max(kheavy_need).max(1.0)\n}\n\nfn split_verdict(splitk: u32, need: f32) -> &'static str {\n    let s = splitk as f32;\n    if s > need {\n        \"excess: pure atomic/combine waste\" // log2(s/need)\n    } else if s < need {\n        \"deficit: the K-heavy miss\" // log2(need/s)\n    } else {\n        \"justified\"\n    }\n}\n".to_string(),
        },

        // ── splitk-atomic-free-contention-threshold — the epilogue economics fork (E) ──
        KernelRule {
            rule_id: "splitk-atomic-free-contention-threshold".to_string(),
            gpu_concept: "The split-K finalize fork — in-place atomicAdd into the output vs the atomic-free two-kernel form (plain stores into a partial[SPLITK, M, N] workspace plus a second bandwidth-bound reduce kernel) — is keyed on atomic CONTENTION scaling with SPLITK * M * N, and it carries a cost side the atomic arm does not pay: \"The deferred split-K finalize (g<w>k) writes + re-reads a full free-size partial workspace and launches the combine kernel — a round-trip volume the in-place atomic g<w>a finalize does not pay\" (search/features.py:694-697). The fork is a SIGNED interaction, not a linear weight, and the threshold is FITTED, not hand-set — verbatim (search/prior/linear_model.py:84-93): \"The split-K finalize interaction, the one part of the quality that is NOT a linear weight: above threshold splits REWARD the deferred combine kernel, below it PENALIZE so a narrow split keeps the cheap atomicAdd fast path. The atomic finalize scores zero either way (finalize_kernel is 0), keeping its geometry-driven rank.\" / \"return weight * finalize_kernel * ((splitk >= threshold) * 2.0 - 1.0)\" — and the fitting discipline is the point: \"a hand-set constant here would be a constant the fit optimizes around\" (:90-92). Integrity half, the featurization-bug lesson (features.py:510-514): \"dropping it leaves a default atomic in place, so D_finalize_kernel goes dead (0.0) on the affected rows and the offline prior's atomic-free split interaction never fires (found scalar-side by the 2026-07-07 reduce-featurization tests; the warp tier repeated the same drop until 2026-07-28)\" — the fork key must be STAMPED on every candidate row or the interaction silently dead-weights to the atomic default; the inert defaults are spelled once for all three readers (linear_model.py:78-81: GATE_DEFAULTS = {D_finalize_kernel: 0.0, D_splitk: 1.0}). Legality preconditions ride from split-k-atomic-arm-legality (this batch): the atomic arm must be semantically legal before its cheapness matters. Article corroboration (§Split-K): atomics are \"cheap when there are few of them, but the contention grows with SPLITK * M * N ... Past some count it is faster to drop the atomics entirely\". Honest NotBenchable (CUDA contention outcomes; the fitted threshold is pool-specific, not portable — the DECISION STRUCTURE and the stamping lesson are the transferable content). Distinct from target-tile-split-k-deterministic-two-dispatch (E — forks on DETERMINISM/contract; this forks on CONTENTION economics; the same partials + fixed-order-reduce skeleton with a different fork key — composable, a consumer can require both at once), from splitk-width-shape-need-gate (this batch — sizes the split; this chooses the epilogue FOR that split), from stripe-sms-l2-semaphore-reduce (E — the ONE-kernel semaphore-combine arm between the two), and from split-reduction-scalar-prepass (E — a prepass partial reduction before the main kernel, a different reduction shape). Category E (parallelism). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — search/prior/linear_model.py:60-93; search/features.py:508-515, :693-697. Batch 137 / Plan 116.".to_string(),
            ref_shape: "// naive: the fork key (finalize flag) dropped from the featurizer — every\n// candidate row reads the default \"atomic\" finalize, so the signed\n// interaction term goes dead (0.0) and the deferred arm can never win.\n// Found by the reduce-featurization tests; the warp tier repeated the\n// same drop for three weeks.\n#[derive(Clone, Copy, Default)]\nstruct CandidateRow {\n    splitk: u32,\n    finalize_kernel: u32, // dropped: always the default 0 (\"atomic\")\n}\n\nfn score_interaction(row: &CandidateRow, weight: f32, threshold: u32) -> f32 {\n    // weight * finalize * ((splitk >= threshold) * 2 - 1): with finalize\n    // hard-zeroed the WHOLE term is 0 either way — the fit optimizes\n    // around a constant and the deferred kernel is never ranked.\n    weight * row.finalize_kernel as f32 * sign(row.splitk, threshold)\n}\n\nfn sign(splitk: u32, threshold: u32) -> f32 {\n    if splitk >= threshold { 1.0 } else { -1.0 }\n}\n".to_string(),
            opt_pattern: "// optimized: stamp the fork key on EVERY row, fit (never hand-set) the\n// threshold, and price the round-trip cost side the atomic arm skips.\n#[derive(Clone, Copy)]\nstruct CandidateRow {\n    splitk: u32,\n    finalize_kernel: u32, // STAMPED per row: 0 = atomic, n = deferred g<n>k\n    roundtrip_bytes: u64, // the deferred arm's workspace volume\n}\n\nfn atomic_free_term(row: &CandidateRow, weight: f32, threshold: u32) -> f32 {\n    // above threshold: REWARD deferred; below: PENALIZE (the atomic's own\n    // finalize score is zero either way, keeping its geometry-driven rank)\n    weight * row.finalize_kernel as f32 * sign(row.splitk, threshold)\n}\n\nfn sign(splitk: u32, threshold: u32) -> f32 {\n    if splitk >= threshold { 1.0 } else { -1.0 }\n}\n\nfn roundtrip_cost(row: &CandidateRow) -> u64 {\n    match row.finalize_kernel {\n        0 => 0, // in-place atomic pays no workspace round-trip\n        _ => row.roundtrip_bytes,\n    }\n}\n".to_string(),
        },

        // ── ldmatrix-pair-x2-to-x4-adjacency — the fragment-load fusion (L) ──
        KernelRule {
            rule_id: "ldmatrix-pair-x2-to-x4-adjacency".to_string(),
            gpu_concept: "Two atom-adjacent ldmatrix.x2 fragment loads — the +8-element second fragment of one x4 — fuse into one ldmatrix.x4 (or .x4.trans): a bit-identical pure instruction-count transform that halves the drain's ldmatrix issue count. Legality is judged structurally on the two loads, verbatim (kernel/096_pair_ldmatrix_loads.py:11-24): \"both staged role-b, same slab / ldm / b_trans / swizzle mode (the drain's swizzle XOR is per-lane address-based, so it commutes with the paired lane map — each lane un-permutes its own 16 B chunk), no masks\"; adjacency is per orientation — \"transposed-B (N-major slab): equal K col, N row exactly +8 — the pair is one plain x4 ... canonical-B (K-major slab): equal K row, col exactly +8 — the pair is one x4.trans\" — the step being one 8x8 ldmatrix matrix (\"the fragment adjacency step, in elements (16 B of b16)\"), and \"The +8-half offsets are 16 B, so every paired lane address keeps ldmatrix's 16 B alignment\" (:14-20, :44-46). Motion rule: \"the second load moves UP to the first's position: every intervening stmt must be barrier-free straight-line code that neither redefines either fragment nor defines a free var of the moved load's index\" (:21-23); the WAR subtlety is load-specific (:125-136): an intervening READ of the MOVED fragment blocks (\"its pre-move value — e.g. the previous streaming step's — would be clobbered early\") while \"Reading the KEPT fragment is fine — the pair fills it at its original position\". Byte slabs are excluded — \"a staged byte-slab (fp8) drain is a cooperative gather, not an ldmatrix — nothing to pair\" (:106-107). \"the paired kernel is bit-identical to its unpaired sibling. Idempotent: a paired load (pair_frag set) is never a candidate, so a re-run finds nothing and skips\" (:26-29). Honest split: NotBenchable as a PERF claim (LSU/issue-count wins are ptxas-measured CUDA); the bit-identity is construction-provable and unit-testable anywhere. Distinct from ldmatrix-mma-layout-loads (L — produce the fragment layout AT load time vs lane-side math; no fusion of loads — this fuses two loads into one instruction), from mma-fragment-layout-m16n8k16 (B — the atom shape itself), from register-double-buffer-operand-pipeline (A — hides fragment-load latency in TIME via double buffering; this merges loads in SPACE — complementary), and from xor-swizzle-smem-static-index-tables (A — the TABULATION axis of the same address transform; the paired lane map must COMMUTE with it — legality condition one, not a duplicate). Category L (conv-as-GEMM + layout). Source: cloudrift-ai/emmy @ 1c058c9d (Apache-2.0) — 096_pair_ldmatrix_loads.py:10-50, :105-140. Batch 137 / Plan 116. RIDER (Batch 235 / Plan 237 / Research 267 -- the width-matched loader face, upstream mma.cuh, ggml-org/llama.cpp #29353 @ merge 62df1815 / head dde6a4d93, MIT -- count-neutral): a shared ldmatrix loader must issue the width the TILE needs, never the width one call site prefers -- load_ldmatrix[_trans]_swizzled widened static_assert(I == 16) to static_assert(I == 8 || I == 16, \"bad tile width\") and splits the PTX by tile width: I==16 keeps ldmatrix.sync.aligned.m8n8.x4.b16 (four destination registers), I==8 issues ldmatrix.sync.aligned.m8n8.x2.b16 (two) -- and the lane map must WRAP for the narrow width, verbatim: const int j = ((threadIdx.x / t.I) * (t.J / 2)) % t.J; (the (threadIdx.x / t.I) * (t.J / 2) product overruns t.J once I < 16 -- the wider lane groups compute j = 8 and j = 12 outside an 8-wide tile's column span; the modulo folds them back). The trans twin pins the 16-row addressing instead -- const int i = threadIdx.x % 16; const int j = I == 16 ? (threadIdx.x / 16) * (t.J / 2) : 0; -- and takes ldmatrix.sync.aligned.m8n8.x2.trans.b16 at the narrow width. DECISION CONTENT: an x4 under an 8-wide tile would stage two 8x8 matrices the tile never consumes, with lane groups addressing rows outside the tile's span -- width-matching is the load-correctness precondition, not an issue-count nicety; the swizzle math (offset_ij = swizzle(offset + i * stride + j, i)) stays the only address transform on either width. COMPOSITION with this rule (not a duplicate -- the opposite direction, adjudicated in Research 266): pick the width the tile needs first (this rider, per-loader), then fuse atom-adjacent loads when two x2s are pairable (this rule's law, per-pair) -- both reduce ldmatrix issue count without changing any staged byte.".to_string(),
            ref_shape: "// naive: the B drain issues two x2 fragment loads for atom-adjacent slabs\n// of one x4's span — double the ldmatrix issues, straight-line between.\n#[derive(Clone, Copy)]\nenum LdMatrix {\n    X2 { row: usize, col: usize },\n    X4 { row: usize, col: usize },\n}\n\nfn drain_b_pair(k_row: usize, n_col: usize) -> Vec<LdMatrix> {\n    // canonical-B (K-major): same K row, cols exactly +8 (one 8x8 atom)\n    vec![\n        LdMatrix::X2 {\n            row: k_row,\n            col: n_col,\n        },\n        LdMatrix::X2 {\n            row: k_row,\n            col: n_col + 8, // the x4's second half, issued separately\n        },\n    ]\n}\n".to_string(),
            opt_pattern: "// optimized: fuse the adjacent pair into one x4 when legality holds —\n// same slab/ldm/b_trans/swizzle, no masks, barrier-free straight-line\n// between, nothing redefines either fragment, no read of the MOVED one.\n#[derive(Clone, Copy)]\nstruct FragLoad {\n    slab: usize,\n    b_trans: bool,\n    row: usize,\n    col: usize,\n}\n\nconst ATOM8: usize = 8; // one 8x8 ldmatrix matrix, in elements (16 B b16)\n\nfn delta(x: usize, y: usize) -> usize {\n    y.abs_diff(x)\n}\n\nfn pairs_with(a: &FragLoad, b: &FragLoad) -> bool {\n    if a.slab != b.slab || a.b_trans != b.b_trans {\n        return false;\n    }\n    match a.b_trans {\n        // N-major: N rows adjacent, same K col\n        true => delta(a.row, b.row) == ATOM8 && a.col == b.col,\n        // K-major: same K row, cols adjacent\n        false => a.row == b.row && delta(a.col, b.col) == ATOM8,\n    }\n}\n\nfn fuse(pair: [FragLoad; 2]) -> Option<FragLoad> {\n    if pairs_with(&pair[0], &pair[1]) {\n        Some(pair[0]) // one x4 at the FIRST's position; the second moves up\n    } else {\n        None\n    }\n}\n".to_string(),
        },
    ]
}
